{"relative_path": "factory/temp/factory/infra/validation.py", "function_name": "check_plan_invariants", "new_function_code": "def check_plan_invariants(plan) -> list[str]:
    """Return violation strings (empty list = plan OK).

    Checks: (1) every coder task lists exactly 1 file; (2) file paths are disjoint
    across all coder tasks. Runs on BOTH planner and supervisor_plan output.
    """
    violations: list[str] = []
    workplan = _get_workplan(plan)
    if not workplan:
        violations.append('workplan or strategy.parallelisable_workplan is missing or null.')
        return violations
    groups = getattr(workplan, 'groups', []) or []
    tasks = _collect_tasks(groups)
    _check_task_file_paths(tasks, violations)
    return violations


def _get_workplan(plan) -> object:
    """Extract workplan from plan or plan.strategy."""
    workplan = getattr(plan, 'workplan', None)
    if not workplan:
        strategy = getattr(plan, 'strategy', None)
        if strategy:
            workplan = getattr(strategy, 'parallelisable_workplan', None)
    return workplan


def _collect_tasks(groups: list) -> list:
    """Flatten all tasks from a list of groups."""
    tasks: list = []
    for group in groups or []:
        tasks.extend(getattr(group, 'tasks', []) or [])
    return tasks


def _check_task_file_paths(tasks: list, violations: list[str]) -> None:
    """Check that each task has exactly 1 file path and no duplicates."""
    seen: set[str] = set()
    for task in tasks:
        fps = getattr(task, 'file_paths', None) or []
        if len(fps) != 1:
            violations.append(f"task {getattr(task, 'id', '?')} lists {len(fps)} files (exactly 1 required)")
        for fp in fps:
            if fp in seen:
                violations.append(f'file collision: {fp} in multiple tasks')
            seen.add(fp)"}

