def _check_file_collisions(fps: list, seen: set[str], violations: list[str]) -> None:
    """Detect duplicate file paths across tasks."""
    for fp in fps:
        if fp in seen:
            violations.append(f'file collision: {fp} in multiple tasks')
        seen.add(fp)"}
